mapper.update:
UPDATE knowledge_document SET bucket_name=#{bucketName}, object_key=#{objectKey},
    content_url=#{contentUrl}, status=#{status}, chunk_count=#{chunkCount},
    error_message=#{errorMessage}, update_time=#{updateTime}
WHERE document_id=#{documentId}

mapper.select:
SELECT  FROM knowledge_document
WHERE knowledge_base_id=#{knowledgeBaseId}
ORDER BY create_time DESC, document_id DESC LIMIT #{limit} OFFSET #{offset}
